// src/app/guards/auth.guard.ts
var authGuard = () => {
  const authService = inject2(AuthService);
  const router = inject2(Router);
  if (authService.isLoggedIn()) {
    return true;
  }
  router.navigate(["/signin"]);
  return false;
};

// src/app/guards/auth-redirect.guard.ts
var authRedirectGuard = () => {
  const authService = inject2(AuthService);
  const router = inject2(Router);
  if (authService.isLoggedIn()) {
    router.navigate(["/"]);
    return false;
  }
  return true;
};

// src/app/guards/role.guard.ts
var roleGuard = () => {
  const authService = inject2(AuthService);
  const router = inject2(Router);
  const user = authService.currentUserValue;
  if (!user)
    return true;
  if (user.role !== void 0 && user.role !== "ADMIN") {
    console.log("\u{1F6AB} RoleGuard: Access restricted for non-ADMIN user. Redirecting to Send Messages.");
    router.navigate(["/messages/send"]);
    return false;
  }
  return true;
};

